<template><div class="app-container"><el-button type="primary" @click="openAdd">新增购买套餐</el-button><el-table v-loading="loading" :data="rows" class="mt16"><el-table-column prop="packageName" label="套餐名称"/><el-table-column prop="credits" label="算力"/><el-table-column prop="bonusCredits" label="赠送"/><el-table-column prop="price" label="售价"/><el-table-column prop="description" label="说明"/></el-table><el-dialog v-model="visible" title="购买配置"><el-form :model="form" label-width="90px"><el-form-item label="套餐名称"><el-input v-model="form.packageName"/></el-form-item><el-form-item label="算力"><el-input-number v-model="form.credits" :min="1"/></el-form-item><el-form-item label="售价"><el-input-number v-model="form.price" :min="0" :precision="2"/></el-form-item><el-form-item label="赠送算力"><el-input-number v-model="form.bonusCredits" :min="0"/></el-form-item><el-form-item label="说明"><el-input v-model="form.description"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup name="VizoraPackage">
import { listPackages, addPackage } from '@/api/vizora/operation'
const rows=ref([]), loading=ref(false), visible=ref(false), form=reactive({packageName:'',credits:1000,price:9.9,bonusCredits:0,enabled:1,sortOrder:0,description:''})
async function load(){loading.value=true;try{const r=await listPackages();rows.value=r.rows||[]}finally{loading.value=false}} function openAdd(){visible.value=true} async function save(){await addPackage(form);visible.value=false;load()} load()
</script>
